"""Build the final review from completed tests, never from expected results."""
import json
from pathlib import Path
from chrome_cdp import source_fingerprint

ROOT=Path(__file__).resolve().parents[1]
def read(name):return json.loads((ROOT/'tests'/name).read_text(encoding='utf-8'))
def assert_passed(report):
    assert not report.get('errors') and all(v=='PASS' for v in report['systems'].values()),'failed test report'

def main():
    audit=read('parallax-final-results.json');retina=read('parallax-final-retina-results.json');ambient=read('parallax-ambient-results.json');regression=read('review-results.json')
    matrix=read('parallax-final-performance-matrix.json');background=read('parallax-final-background-performance-results.json');profile=read('parallax-final-profile-results.json')
    before=read('parallax-final-before-background.json');before_profile=read('parallax-final-before-profile.json');before_full=read('parallax-final-before-full.json')
    for report in [audit,retina,ambient,regression]:assert_passed(report)
    assert not regression['summary']['failures'],'regression failed'
    fingerprint=source_fingerprint(ROOT)
    assert all(r['execution']['sourceSha256']==fingerprint for r in [audit,retina,ambient,regression,background,profile]),'test sources do not match final sources'
    assert matrix['sourceSha256']==fingerprint,'benchmark source mismatch'
    for case in matrix['cases']:
        pacing=read(Path(case['framePacingReport']).name)
        assert_passed(pacing);assert pacing['conditions']['menuOverlayHidden'],'pacing measured menu instead of gameplay'
    normal=[r for r in background['performance'] if not r['reduced']];old_normal=[r for r in before['performance'] if not r['reduced']]
    before_mean=sum(r['meanMs'] for r in old_normal)/10;after_mean=sum(r['meanMs'] for r in normal)/10
    summary={'sourceSha256':fingerprint,'regression':regression['summary'],'auditChecks':len(audit['systems']),'retinaAuditChecks':len(retina['systems']),'ambientChecks':len(ambient['systems']),'referenceSamplesPerConfiguration':sum(r['samples'] for r in audit['pixelComparisons']),'maxReferenceChannelDelta':max(r['maximumChannelDelta'] for r in audit['pixelComparisons']+retina['pixelComparisons']),'maxFullSceneDeltaRetina':max(r['maximumChannelDelta'] for r in retina['presentationComparisons']),'visibilitySamples':len(ambient['visibility']),'minDistinctCharacterFraction':min(r['distinctFraction'] for r in ambient['visibility']),'peakParallaxBytes':max(r['peakTextureBytes'] for r in audit['memory']),'disposedParallaxBytes':max(r['afterDisposeBytes'] for r in audit['memory']),'backgroundMeanBeforeMs':before_mean,'backgroundMeanAfterMs':after_mean,'backgroundObservedReductionPercent':100*(1-after_mean/before_mean),'framePacing':[{ 'case':c['case'],'fps':[r['observedFPS'] for r in c['framePacing']],'budgetPasses':11-len(c['budgetFailures'])} for c in matrix['cases']],'certifiesUniversal60FPS':False}
    (ROOT/'tests/parallax-final-summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
    lines=['# BYTE RUNNER — revisão final do parallax','','Implementação finalizada, com otimizações de desenho e apresentação, auditoria de câmera e pixel art, verificação de memória e regressão dos sistemas existentes. As limitações de alta densidade permanecem registradas abaixo.','','[Galeria final](../tests/parallax-final-gallery.html) · [Progresso completo](../PROGRESSO_MAPAS.md)','','## Melhorias e problemas corrigidos','',
    '- Planos estáticos continuam em cache, agora com limites de pixels não transparentes calculados pelo gerador. O desenho pula variantes vazias e recorta cada trecho ao viewport; nenhum trecho de plano é enviado fora da área visível.',
    '- O gradiente de tela inteira que ficava encoberto pelo fundo opaco foi removido do caminho nativo. O fallback anterior continua disponível quando o atlas não está carregado.',
    '- Ventoinhas reutilizam quatro frames raster em cache. A composição regional usa uma superfície fixa de 256 × 256, atualizada somente quando muda a região, a mistura quantizada em 64 passos ou a imagem. Não são criadas novas superfícies por frame nem durante viagens e redimensionamentos.',
    '- Descritores, recortes, condições de reparo e parâmetros de animação foram preparados fora do loop. Arrays de braços de ventoinha e pares de mistura deixaram de ser montados a cada desenho.',
    '- O índice de monitores passou a usar módulo positivo para evitar deslocamentos incorretos com coordenadas negativas. O culling dos sinais de dano considera a extensão real dos pequenos efeitos nas bordas.',
    '- Em DPR efetivo 1 e dimensões lógicas inteiras, o jogo desenha diretamente no Canvas de saída, eliminando a cópia integral do framebuffer. O buffer intermediário é liberado nesse modo. Em DPR maior ou layout fracionário, o caminho escalado continua ativo, com nearest-neighbor.',
    '- Os dois framebuffers são opacos e o estado básico de fonte/alinhamento/traço é definido explicitamente ao iniciar a cena. Os caminhos direto e intermediário produzem os mesmos pixels na comparação em superfícies equivalentes.',
    '- O descarte zera as dimensões das superfícies e remove referências às imagens. A identidade das dez fases, os efeitos discretos e as opções de conforto foram preservados.','','## Arquivos modificados nesta etapa','','| Arquivo ou grupo | Finalidade |','| --- | --- |',
    '| `game.js` | Somente construtores de Canvas e caminho de apresentação; lógica de jogo preservada por normalização exata e hashes. |',
    '| `src/engine/parallax.js` | Recortes visíveis, descritores preparados, cache, métricas e descarte. |',
    '| `src/engine/parallax-life.js` | Cache de ventoinhas e mistura regional, menos alocações e correções de borda/índice. |',
    '| `src/engine/background-scene.js` | Remoção do preenchimento redundante no caminho nativo. |',
    '| `tools/build_environment_art.py` | Geração offline de `frameBounds` por variante. Nenhum redesign de sprites ou paletas. |',
    '| `assets/pixelart/manifest.json`, `src/engine/art-manifest.js` | Metadados de recorte dos atlas. |',
    '| `tools/check_environment.py`, `tools/check_parallax.py`, `tools/check_hardware_depth.py` | Guardas das alterações exatas de apresentação e verificação dos limites dos sprites. |',
    '| `tests/run_review.py`, `tests/parallax-final.js` | Auditoria de referência, três resoluções, câmera, descarte, DPR e captura de evidências. |',
    '| `tests/profile-render.js`, `tests/final-performance.js`, `tests/parallax-frame-pacing.js`, `tests/run_parallax_performance_matrix.py` | Perfil de custos, matriz de resoluções e intervalos reais de RAF. |',
    '| `tests/parallax-depth.js`, `tests/parallax-ambient.js` | Offsets verificáveis mesmo sem blits vazios; limite explícito dos novos caches. |',
    '| `tests/fixtures/parallax-before-final.js`, `tests/fixtures/parallax-life-before-final.js` | Código anterior preservado exclusivamente para comparação nos testes. |',
    '| `tests/report_final_parallax.py`, relatórios JSON, capturas PNG e galeria | Evidências reproduzíveis. |',
    '| `PROGRESSO_MAPAS.md`, este relatório | Registro final e limitações. |','','## Testes realmente executados','','| Teste | Resultado executado |','| --- | --- |',
    f'| Regressão completa — `python tests/run_review.py` | {regression["summary"]["passedSystems"]}/{regression["summary"]["systems"]}; dez fases; {regression["summary"]["captures"]} capturas; zero erros de runtime. |',
    f'| Auditoria final — `--parallax-final` | {len(audit["systems"])}/{len(audit["systems"])} no viewport padrão; {len(retina["systems"])}/{len(retina["systems"])} em 1920 × 1080, DPR 2. |',
    f'| Ambiente, conforto e personagem — `--ambient-only` | {len(ambient["systems"])}/{len(ambient["systems"])}; {len(ambient["visibility"])} posições de apoio reais. |',
    '| Benchmark de fundo — `--ambient-performance` | Dez fases, modo normal e reduzido, 24 frames de aquecimento e 120 amostras por caso. |',
    '| Matriz de desempenho — `tests/run_parallax_performance_matrix.py` | 33 casos de update + draw e 12 amostragens de RAF, incluindo mapa procedural de 24 salas. Reprovações do orçamento ficam registradas. |',
    '| Integridade | `check_parallax.py`, `check_environment.py`, `check_hardware_depth.py`, `check_maps.py`, `check_generation.py` e `git diff --check` executados. |',
    '', 'Os totais são apresentados por suíte e têm cobertura sobreposta. O benchmark não transforma reprovações de orçamento em testes aprovados.','','### Sistemas preservados','',
    'A regressão executou as dez fases, física e colisões, câmeras horizontal/vertical, inimigos e seus ataques, plataformas móveis/temporárias, reparos, todos os tipos de minigame, habilidades, compatibilidade de saves, perguntas e vitória, além de ativação, escudo, fases, telegráficos e derrota de VIRUS ZERO. Os módulos de mapas, runtime, física e câmera permanecem protegidos por hashes. Somente os trechos exatos de apresentação em `game.js` são normalizados para permitir a comparação do restante do arquivo.','','### Câmera, pixel art e leitura','',
    f'A comparação contra o renderer e o módulo ambiental anteriores executou {summary["referenceSamplesPerConfiguration"]} amostras por configuração em 320 × 180, 905 × 644 e 1920 × 1080. Incluiu limites específicos de cada camada, deslocamento diagonal, ida e volta, mudanças rápidas de direção e coordenadas negativas. O maior desvio observado por canal foi {summary["maxReferenceChannelDelta"]} níveis em 255, compatível com a composição em cache; não houve pixels com desvio acima de cinco. A comparação da cena inteira entre apresentação direta e framebuffer, em superfícies físicas equivalentes, teve desvio máximo {summary["maxFullSceneDeltaRetina"]} em DPR 2.',
    'Nearest-neighbor permaneceu desativando suavização no framebuffer, sprites e caches, inclusive após redimensionar. Os recortes são inteiros e as variantes têm margens transparentes verificadas; nenhum sprite foi suavizado ou substituído por desenho de outra identidade.',
    f'No pior dos {summary["visibilitySamples"]} apoios auditados, {summary["minDistinctCharacterFraction"]*100:.2f}% dos pixels claros detectados no personagem ficaram pelo menos 40 níveis de luminância acima da cena imediatamente anterior ao seu desenho. A inspeção visual das capturas confirmou os contornos mais fortes de plataformas, personagens, inimigos e equipamentos interativos; os elementos decorativos permanecem escuros e em passes anteriores. Essa é uma amostragem, sem alegação de cobrir toda combinação possível de posição, combate e efeitos.','','## Desempenho e quedas de FPS','','### Fundo isolado, comparação com a etapa anterior','','Condições: Chrome headless, GPU desativada, Canvas 905 × 644; nove posições de câmera; conclusão forçada da rasterização com leitura de um pixel. A referência anterior foi preservada no início desta etapa. Execuções separadas têm variação da máquina.','','| Fase | Média anterior (ms) | Média final (ms) | p95 anterior (ms) | p95 final (ms) |','| --- | ---: | ---: | ---: | ---: |']
    for a,b in zip(old_normal,normal):lines.append(f'| {a["phase"]} | {a["meanMs"]:.2f} | {b["meanMs"]:.2f} | {a["p95Ms"]:.2f} | {b["p95Ms"]:.2f} |')
    lines+=['',f'Média entre fases: {before_mean:.2f} → {after_mean:.2f} ms, diferença observada de {summary["backgroundObservedReductionPercent"]:.1f}%. O perfil anterior de update + draw nesta etapa mediu {before_profile["profile"]["total"]/60:.2f} ms por quadro; o perfil final mediu {profile["profile"]["total"]/60:.2f} ms. Esses tempos não substituem os intervalos de apresentação abaixo.','','### Apresentação real por RAF','','Fases amostradas: Hardware, Software, Servidores e mapa procedural de 24 salas. Cada caso teve 12 quadros de aquecimento e 90 intervalos nativos de `requestAnimationFrame`, com a fase iniciada e o menu fechado, passo de simulação 1/60 e deslocamento diagonal sintético da câmera. O teste inclui o compositor do navegador, além do update + draw.','','| Configuração | Canvas lógico / DPR efetivo | FPS observados nos quatro cenários | Intervalo p95 (ms) | Orçamento CPU p95 ≤ 16,7 ms |','| --- | --- | --- | --- | --- |']
    for case in matrix['cases']:
        p=case['performance'][0];fps=', '.join(f'{r["observedFPS"]:.1f}' for r in case['framePacing']);p95=', '.join(f'{r["p95IntervalMs"]:.1f}' for r in case['framePacing'])
        lines.append(f'| {case["case"]} | {p["width"]:g} × {p["height"]:g} / {p["pixelRatio"]:g} | {fps} | {p95} | {11-len(case["budgetFailures"])}/11 aprovados |')
    lines+=['','O desktop ainda teve quedas pontuais e um caso acima do orçamento de CPU; o modo de alta densidade manteve quedas mais fortes e reprovou o orçamento nas onze cargas sem GPU. O mobile medido atingiu aproximadamente 60 FPS nessa simulação. Não há garantia universal de 60 FPS. Uma medição com GPU habilitada, hardware real e sessões humanas longas permanece necessária para concluir sobre dispositivos específicos.','','## Memória e reaproveitamento','',
    f'Pico de superfícies do parallax: {summary["peakParallaxBytes"]:,} bytes ({summary["peakParallaxBytes"]/1048576:.3f} MiB), dentro do limite auditado de 4,25 MiB. O descarte deixou {summary["disposedParallaxBytes"]} bytes nessas superfícies, mesmo com o objeto de serviço ainda referenciado. O quadro regional adicional ocupa 256 KiB; cada atlas de quatro ventoinhas ocupa 6.400 bytes. Esse pequeno custo fixo de memória reduz operações e reconstruções de desenho.',
    'Após aquecimento, sessenta desenhos na mesma câmera criaram zero novos canvases, mantiveram os mesmos strips e não reconstruíram a mistura regional. Viagens longas e redimensionamentos não aumentaram esses caches. O mapa grande auditado tem 14.592 × 2.304 pixels; o parallax não aloca texturas do tamanho do mundo.',
    'As contagens são das superfícies RGBA gerenciadas, não do RSS total do processo, heap completo ou VRAM. O pool compartilhado de PNGs e os caches de terreno têm limites próprios; a matriz também registra bytes dos framebuffers e limite de 96 chunks. Em apresentação direta, o framebuffer intermediário tem dimensão zero.','','## Correções de metodologia e limites','',
    'A auditoria inicial em Retina comparava uma superfície física maior com uma menor ao forçar DPR 1; isso permitia que efeitos fora da borda lógica entrassem na comparação. A câmera também começava fora do envelope normal de acompanhamento. Os fixtures foram corrigidos, sem relaxar o limite de pixels ou alterar a física/câmera. A reprovação inicial está em `tests/parallax-final-initial-retina.json`.',
    'A primeira medição por RAF deixava o menu com blur sobre o Canvas. O teste passou a iniciar efetivamente a fase e verificar que o menu está oculto. A matriz inicial foi preservada em `tests/parallax-final-initial-matrix.json`; as medições finais acima são do jogo iniciado.',
    'A equivalência numérica permite arredondamento de composição do cache, não alterações de silhueta. Os testes de leitura e emendas cobrem posições e tempos definidos, sem substituir inspeção em todos os monitores, zooms, drivers ou estados possíveis. A matriz foi executada em Chrome headless com GPU desativada; não houve teste humano contínuo nem medição de bateria.','','## Reprodução e evidências','','```powershell','python tools/build_environment_art.py --parallax-all','python tests/run_review.py --parallax-final','python tests/run_review.py --parallax-final --viewport 1920x1080 --dpr 2 --result-label parallax-final-retina','python tests/run_review.py --ambient-only','python tests/run_review.py --ambient-performance --result-label parallax-final-background-performance','python tests/run_review.py --profile-render --result-label parallax-final-profile','python tests/run_parallax_performance_matrix.py','python tests/run_review.py','python tests/report_final_parallax.py','```','',
    'Os cinco scripts de integridade e `git diff --check` completam a verificação. `--performance-only` mantém retorno 1 quando há reprovações de orçamento; a matriz conserva essas reprovações, completando a medição se não houver erro de runtime, cache ou fonte.',
    f'Fontes finais: `{fingerprint}`. Resumo: `tests/parallax-final-summary.json`. Resultados completos: `tests/parallax-final-results.json`, `tests/parallax-final-retina-results.json`, `tests/parallax-ambient-results.json`, `tests/review-results.json` e `tests/parallax-final-performance-matrix.json`.']
    (ROOT/'docs/parallax-final-review.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    html=['<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>BYTE RUNNER — revisão final</title><style>body{margin:24px;background:#08151e;color:#dcebf0;font:16px system-ui}main{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}img{width:100%;image-rendering:pixelated}figure{margin:0}figcaption{padding:8px 0}h2{grid-column:1/-1}a{color:#8ce0cc}@media(max-width:760px){main{grid-template-columns:1fr}}</style><h1>BYTE RUNNER — revisão final</h1><p>Capturas reais após a auditoria, em viewport padrão e DPR 2. Clique para abrir em tamanho original.</p><main>']
    for i in range(10):
        html.append(f'<h2>Fase {i+1:02}</h2>')
        for title,report in [('Viewport padrão',audit),('1920 × 1080, DPR 2',retina)]:
            shot=next(s for s in report['snapshots'] if s['phase']==i+1);file=Path(shot['file']).name
            html.append(f'<figure><a href="{file}"><img loading="lazy" src="{file}" alt="Fase {i+1}: {title}"></a><figcaption>{title}</figcaption></figure>')
    html.append('</main></html>');(ROOT/'tests/parallax-final-gallery.html').write_text(''.join(html),encoding='utf-8')
    print(json.dumps(summary,indent=2))

if __name__=='__main__':main()
